#define KELLY_DECOMP_FULL_FEMENU_ENTRY
#define KELLY_DECOMP_FULL_FEMULTI_MENU
#define KELLY_DECOMP_SAVELOAD_VTABLE
#include "KS/SRC/ks/FEMenu_shared.h"
#undef KELLY_DECOMP_SAVELOAD_VTABLE
#undef KELLY_DECOMP_FULL_FEMULTI_MENU
#undef KELLY_DECOMP_FULL_FEMENU_ENTRY

class PanelAnim;

class matrix4x4 {
    float values[16] __attribute__((aligned(16)));
};

struct nglQuadVertex {
    float X;
    float Y;
    float U;
    float V;
    unsigned int Color;
};

struct nglTexture;

struct nglQuad {
    nglQuadVertex Verts[4];
    float Z;
    unsigned int MapFlags;
    unsigned int BlendMode;
    unsigned int BlendModeConstant;
    nglTexture *Tex;
};

struct recti {
    int x0;
    int y0;
    int x1;
    int y1;
};

class PanelQuad {
protected:
    bool isAnim;
    int fade;
    float fade_alpha;
    float fade_timer;
    float mask;
    int maskType;
    PanelAnim *anim;
    nglQuad quad;
    bool drawOn;
    int rotate;
    float rotation;
    float rotate_x;
    float rotate_y;
    int layer;
    float r;
    float g;
    float b;
    float a;
    float x1;
    float y1;
    float x2;
    float y2;
    float width;
    float height;
    float width_a;
    float height_a;
    matrix4x4 matrix;
    bool on_menu;
    bool clip;
    recti clipping;

public:
    matrix4x4 Xform;
    stringx name;
    bool dont_draw;
    float z;
    float u1;
    float v1;
    float u2;
    float v2;
    PanelQuad *next;

    virtual ~PanelQuad();
    virtual void Init(
        float x1, float y1, float x2, float y2,
        float r, float g, float b, float a,
        float u1, float v1, float u2, float v2,
        float z, matrix4x4 object_matrix);
    virtual void TurnOn(bool enabled);
};

struct vector2d {
    float x;
    float y;
};

struct MemCard {
    int free;
    bool exists;
    bool changed;
    bool available;
    bool ask_format;
    bool saved_games;
    int status;
};

class SaveLoadFrontEnd {
public:
    enum { num_each = 15 };
};

class BoxText;

class NamesMenu : public FEMultiMenu {
    int type;
    bool save;
    vector2d card_center;
    SaveLoadFrontEnd *sl_parent;
    int check_cards_counter;
    int arrow_num;
    int arrow_counter;
    bool empty[SaveLoadFrontEnd::num_each];
    MemCard cards[2];
    stringx blank_name;
    int active_card;
    int adjusted_active_card;
    bool cardSide;
    PanelQuad *box;
    PanelQuad *arrows[2][2];
    PanelQuad *lines[10];
    PanelQuad *top_line;
    PanelQuad *side_line;
    FEMenuEntry *entry[SaveLoadFrontEnd::num_each + 2];
    BoxText *message;
    BoxText *freeSpace;
    bool draw_message;

public:
    void TurnPQ(bool enabled);
    void TurnPQLines(bool enabled);
};

__asm__(".equ TurnPQLines__9NamesMenub, 0x0019ED70");

void NamesMenu::TurnPQ(bool on)
{
	box->TurnOn(on);
	top_line->TurnOn(on);
	side_line->TurnOn(on);
	arrows[0][0]->TurnOn(on);
	arrows[0][1]->TurnOn(false);
	arrows[1][0]->TurnOn(on);
	arrows[1][1]->TurnOn(false);
	TurnPQLines(on);
}
